n = 0
for cod, conteudo in AMP.items():
    alvo = next((f for f in P.glob(f"{cod}-*.md")), None)
    if not alvo:
        print(f"!! sem ficha: {cod} (registrado na Colecionar Incertezas)")
        continue
    txt = alvo.read_text(encoding="utf-8")
    if "## Ampliação — P2025-03-15" in txt:
        print(f"!! já ampliada: {cod}")
        continue
    secao = f"\n## Ampliação — P2025-03-15\n\n{conteudo.strip()}\n"
    if "## Fontes" in txt:
        txt = txt.replace("## Fontes", secao + "\n## Fontes", 1)
    else:
        txt = txt.rstrip() + "\n" + secao + "\n---\n"
    alvo.write_text(txt, encoding="utf-8")
    n += 1
print(f"fichas ampliadas: {n}")
